(function(){'use strict';const SRC='/static/ariella-avatar-approved.jpg?v=20260915';function setText(e,v){if(e&&e.textContent!==v)e.textContent=v}function avatars(root){(root||document).querySelectorAll('.ac-avatar,.ac-mini-avatar').forEach(e=>{let i=e.querySelector('img');if(!i){i=document.createElement('img');i.className='ariella-avatar-img';i.alt='Ariella';e.textContent='';e.appendChild(i)}if(i.getAttribute('src')!==SRC)i.setAttribute('src',SRC)})}function ui(){const c=document.getElementById('ariellaDesktopChat');if(!c)return;const en=(document.documentElement.lang||'').toLowerCase().startsWith('en');c.dir=en?'ltr':'rtl';setText(c.querySelector('.ac-head-copy strong'),en?'Ariella — Your Personal Travel Agent':'אריאלה — סוכנת הנסיעות האישית שלך');setText(c.querySelector('.ac-online'),en?'Available now':'זמינה עכשיו');setText(c.querySelector('.ac-send'),en?'Send':'שליחה');setText(c.querySelector('.ac-summary>strong'),en?'My Vacation':'החופשה שלי');const L=en?{destination:'Destination',dates:'Dates',travelers:'Travelers',budget:'Budget',flight:'Flight',baggage:'Baggage'}:{destination:'יעד',dates:'תאריכים',travelers:'נוסעים',budget:'תקציב',flight:'טיסה',baggage:'כבודה'};Object.keys(L).forEach(k=>setText(c.querySelector('[data-summary-key="'+k+'"] b'),L[k]));if(!en){const M={Montenegro:'מונטנגרו',July:'יולי',January:'ינואר',February:'פברואר',March:'מרץ',April:'אפריל',May:'מאי',June:'יוני',August:'אוגוסט',September:'ספטמבר',October:'אוקטובר',November:'נובמבר',December:'דצמבר',direct:'ישירה',connection:'קונקשן',trolley:'טרולי',carry_on:'תיק יד',checked_bag:'מזוודה'};c.querySelectorAll('.ac-detail span').forEach(s=>{let t=s.textContent;Object.keys(M).forEach(k=>t=t.replace(new RegExp('\\b'+k+'\\b','gi'),M[k]));setText(s,t)})}avatars(c)}function init(){ui();const c=document.getElementById('ariellaDesktopChat');if(!c)return;const i=c.querySelector('#ariellaChatInput'),b=c.querySelector('#ariellaChatSend');if(b&&i)b.addEventListener('click',()=>setTimeout(()=>i.value='',0));if(i)i.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey)setTimeout(()=>i.value='',0)});new MutationObserver(m=>m.forEach(x=>x.addedNodes.forEach(n=>{if(n.nodeType===1)avatars(n)}))).observe(c,{childList:true,subtree:true});setInterval(ui,700)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init()})();